const inputRoot = $('Receive request').first().json;
const input = inputRoot.body ?? inputRoot;
const ai = $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || input.live_probe?.request_id || `req_${executionId}`;
const aiText = ai.output || ai.text || ai.response || ai.message || '';
const isResume = input.intent === 'resume_after_approval' || input.input?.approved === true;
const approval = isResume ? null : {
  required: true,
  gate: 'requires_human_action',
  summary: 'Human approval is required before Agentic Butler executes external work, sends messages, creates meetings, or creates a new skill version.',
  proposed_action: input.intent === 'create_skill' ? 'Create a pending skill draft and keep it behind human approval.' : 'Prepare the skill output and pause before any external action.'
};
const response = {
  envelope_version: input.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'agentic_butler',
  status: isResume ? 'completed' : 'approval_required',
  approval,
  output: {
    summary: aiText || (isResume ? 'Agentic Butler resumed after human approval.' : 'Agentic Butler AI Agent completed planning and paused at the approval gate.'),
    approval_request: approval,
    skill_run: { mode: isResume ? 'resumed_after_approval' : 'approval_gated', execute: Boolean(isResume) },
    contract_stage: 'ai_agent_normalized',
    ai_agent: { integrated: true, node: 'Agentic Butler AI Agent' }
  },
  trace: { stored: true, trace_id: `n8n_exec_${executionId}`, used_agents: ['agentic_butler_ai_agent', 'skill_orchestrator_internal_component', 'actor_twin_checkpoint_boundary'], target_agent: 'agentic_butler', route_decision: input.intent === 'create_skill' ? 'create_skill' : 'activate_skill', handoff_status: isResume ? 'resumed' : 'approval_required', parent_trace_id: input.context?.handoff_trace_id || input.context?.actor_trace_id || '', ai_agent_integrated: true }
};
return [{ json: response }];

